package br.com.admeclesial.application.projeto;
import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService;
import br.com.admeclesial.domain.financeiro.ItemOrcamento; import br.com.admeclesial.domain.financeiro.Orcamento; import br.com.admeclesial.domain.financeiro.StatusOrcamento; import br.com.admeclesial.domain.projeto.*; import br.com.admeclesial.infrastructure.persistence.financeiro.ItemOrcamentoRepository; import br.com.admeclesial.infrastructure.persistence.financeiro.OrcamentoRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.projeto.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*;
@Service public class ProjetoApplicationService { @Autowired SegurancaOrganizacaoService seguranca;
 final ProjetoRepository repo; final OrganizacaoEclesialRepository org; final ItemOrcamentoRepository itens; final OrcamentoRepository orcamentos; final FonteRecursoProjetoRepository fontes;
 public ProjetoApplicationService(ProjetoRepository r,OrganizacaoEclesialRepository o,ItemOrcamentoRepository i,OrcamentoRepository orc,FonteRecursoProjetoRepository f){repo=r;org=o;itens=i;orcamentos=orc;fontes=f;}
 @Transactional public Projeto criar(ProjetoRequest r){if(seguranca!=null)seguranca.validarAcesso(r.organizacaoEclesialUuid());var o=org.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new IllegalArgumentException("Organização não encontrada."));if(!o.isAtivo())throw new IllegalArgumentException("Organização inativa.");if(r.dataInicio()!=null&&r.dataFim()!=null&&r.dataFim().isBefore(r.dataInicio()))throw new IllegalArgumentException("Data final não pode ser anterior à inicial.");Long itemId=null;if(r.itemOrcamentoUuid()!=null){var item=itens.findByUuid(r.itemOrcamentoUuid()).orElseThrow(()->new IllegalArgumentException("Item de orçamento não encontrado."));var orc=orcamentos.findById(item.getOrcamentoId()).orElseThrow(()->new IllegalArgumentException("Orçamento do item não encontrado.")); if(!orc.getOrganizacaoEclesialId().equals(o.getId()))throw new IllegalArgumentException("O item de orçamento deve pertencer à organização do projeto."); if(orc.getStatus()==StatusOrcamento.CANCELADO)throw new IllegalArgumentException("Não é possível vincular item de orçamento cancelado."); itemId=item.getId();}var e=new Projeto();e.setOrganizacaoEclesialId(o.getId());e.setItemOrcamentoId(itemId);e.setTipo(r.tipo());e.setStatus(StatusProjeto.PLANEJADO);e.setNome(r.nome().trim());e.setDescricao(r.descricao());e.setDataInicio(r.dataInicio());e.setDataFim(r.dataFim());e.setValorEstimado(r.valorEstimado());return repo.save(e);}
 @Transactional public Projeto atualizar(UUID uuid, ProjetoRequest r){var e=buscar(uuid);if(seguranca!=null)seguranca.validarAcesso(r.organizacaoEclesialUuid());var o=org.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new IllegalArgumentException("Organização não encontrada."));if(!o.isAtivo())throw new IllegalArgumentException("Organização inativa.");if(r.dataInicio()!=null&&r.dataFim()!=null&&r.dataFim().isBefore(r.dataInicio()))throw new IllegalArgumentException("Data final não pode ser anterior à inicial.");Long itemId=null;if(r.itemOrcamentoUuid()!=null){var item=itens.findByUuid(r.itemOrcamentoUuid()).orElseThrow(()->new IllegalArgumentException("Item de orçamento não encontrado."));var orc=orcamentos.findById(item.getOrcamentoId()).orElseThrow(()->new IllegalArgumentException("Orçamento do item não encontrado.")); if(!orc.getOrganizacaoEclesialId().equals(o.getId()))throw new IllegalArgumentException("O item de orçamento deve pertencer à organização do projeto."); if(orc.getStatus()==StatusOrcamento.CANCELADO)throw new IllegalArgumentException("Não é possível vincular item de orçamento cancelado."); itemId=item.getId();}e.setOrganizacaoEclesialId(o.getId());e.setItemOrcamentoId(itemId);e.setTipo(r.tipo());e.setNome(r.nome().trim());e.setDescricao(r.descricao());e.setDataInicio(r.dataInicio());e.setDataFim(r.dataFim());e.setValorEstimado(r.valorEstimado());return repo.save(e);}
 @Transactional public Projeto iniciar(UUID uuid){var e=buscar(uuid);if(e.getStatus()!=StatusProjeto.PLANEJADO)throw new IllegalArgumentException("Somente projeto planejado pode entrar em execução.");e.setStatus(StatusProjeto.EM_EXECUCAO);return repo.save(e);}
 @Transactional public Projeto concluir(UUID uuid){var e=buscar(uuid);if(e.getStatus()!=StatusProjeto.EM_EXECUCAO)throw new IllegalArgumentException("Somente projeto em execução pode ser concluído.");e.setStatus(StatusProjeto.CONCLUIDO);if(e.getDataFim()==null)e.setDataFim(LocalDate.now());return repo.save(e);}
 @Transactional public Projeto cancelar(UUID uuid){var e=buscar(uuid);if(e.getStatus()==StatusProjeto.CONCLUIDO||e.getStatus()==StatusProjeto.CANCELADO)throw new IllegalArgumentException("Projeto não pode ser cancelado neste estado.");e.setStatus(StatusProjeto.CANCELADO);return repo.save(e);}
 @Transactional(readOnly=true) public Projeto buscar(UUID uuid){var e=repo.findByUuid(uuid).orElseThrow(()->new IllegalArgumentException("Projeto não encontrado."));if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId());return e;}
 @Transactional(readOnly=true) public List<Projeto> listar(){return repo.findAllByOrderByDataInicioDesc().stream().filter(e -> { try { if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId()); return true; } catch (org.springframework.security.access.AccessDeniedException ex) { return false; }}).toList();}
 @Transactional(readOnly=true) public List<FonteRecursoProjeto> listarFontes(UUID uuid){return fontes.findAllByProjetoIdOrderByIdAsc(buscar(uuid).getId());}
}
